/* Browser-local session manager. No character data is sent to the server. */
(()=>{'use strict';
let uiDocument=document;
const surfaces=new Map([[document,{tab:"actions"}]]), popupTitles={actions:"行動一覧",compare:"期待値",buffs:"盤面の補正"};
const Y=Ygg,$=s=>uiDocument.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const WINDOWS_FILE='Ulfhamr-Windows-v1.13.zip',WINDOWS_DOWNLOAD='downloads/'+WINDOWS_FILE;
const KEY='ygg-round-v1';let db={version:1,characters:[],activeId:null},storageError='';
try{const raw=localStorage.getItem(KEY);if(raw)db=Y.validateDatabase(JSON.parse(raw));}catch(e){storageError='保存データを読めませんでした。元データは上書きせず保持しています。バックアップを書き出してから確認してください。';}
let tab='actions',draft=[],desperate=0,note='',search='',selectedActionId='',pendingImport=null,importMode='progress',compareOpts={attack:'weapon',mental:false,includeDraft:true,mode:'cf',tie:'reroll',minimum:0},calcResult=null;
let compactDesktop=false;
const foldedGroups=new Set(['応用技','AE','バースト']);
const c=()=>db.characters.find(x=>x.id===db.activeId)||db.characters[0];
const symbol='<img class="app-emblem" src="Ulfhamr.svg" alt="">';
function toast(text){const target=$('#toast');target.textContent=text;target.classList.add('show');clearTimeout(target.timer);target.timer=setTimeout(()=>target.classList.remove('show'),4500);}
function save(){if(storageError){toast(storageError);return false;}try{localStorage.setItem(KEY,JSON.stringify(db));return true;}catch(e){storageError='端末への保存に失敗しました。バックアップを書き出してください。';toast(storageError);return false;}}
function download(data,name,type='application/json'){const a=uiDocument.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function input(name,label,value,type='number',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="1"':''} ${attrs}></label>`;}
function select(name,label,value,options){return `<label>${label}<select name="${name}">${options.map(o=>{const[v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;}
function modal(title,body,sub=''){ $('#modal-content').innerHTML=`${c()&&uiDocument===document?'<div class="modal-resources">'+resourceBar(c())+'</div>':''}<div class="modal-title"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button data-do="close" class="ghost" aria-label="閉じる">×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal();syncSurfaceLocks();}
function resource(label,key,max,cls=''){const s=c().state,v=s[key],percent=max?Math.max(0,Math.min(100,100*v/max)):0;return `<button type="button" class="resource ${cls}" data-do="copy-resource" data-key="${key}" title="${esc(Y.resourceCopy(c(),key))} をコピー"><div class="resource-label"><span>${label}</span><span>${key==='rage'?'%':key==='factor'?'Rd':''}</span></div><div class="resource-value">${v}<small>${max&&key!=='rage'?' / '+max:''}</small></div>${max?`<div class="meter"><i style="width:${percent}%"></i></div>`:''}<div class="resource-note">${key==='spent'?`次の因子まで ${5-v%5} PP`:key==='rage'?(v<50?'未活性':v<100?'活性 Lv.'+Math.min(5,Math.floor((v-40)/10)):v<150?'臨界域':'因子崩壊'):key==='factor'?'総消費PPに連動':key==='hp'?'HIT POINTS':'POWER POINTS'}</div></button>`;}
function resourceBar(char){const s=char.state;return `<section class="resource-grid" aria-label="現在の状態">${resource('HP','hp',s.hpMax)}${resource('PP','pp',s.ppMax)}${resource('暴走率','rage',150,'rage')}${resource('因子','factor',0,'factor')}${resource('総消費 PP','spent',0)}${['spe','karma'].map(key=>`<button type="button" class="resource resource-ability" data-do="copy-resource" data-key="${key}" title="${esc(Y.resourceCopy(char,key))} をコピー"><span class="resource-label">${key==='spe'?'SPE':'カルマ'}</span><span class="ability-value">${esc(Y.resourceCopy(char,key).replace(/^(SPE|カルマ) /,''))}</span></button>`).join('')}<button type="button" class="resource-copy-all" data-do="copy-resource" data-key="all">全状態を1行でコピー</button></section>`;}
function renderOne(){const char=c();if(char&&!db.activeId)db.activeId=char.id;
$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${symbol}</div><div><strong>情報拡張装置<br>【ウールヴハム】</strong><small>SESSION COMPANION</small></div></div><div><div class="side-label">CHARACTERS <span>${db.characters.length.toString().padStart(2,'0')}</span></div><div class="side-characters">${db.characters.map((x,i)=>`<button class="character ${char?.id===x.id?'active':''}" data-do="switch" data-id="${esc(x.id)}"><span class="avatar">${(i+1).toString().padStart(2,'0')}</span><span class="char-text"><b>${esc(x.name)}</b><small>${esc(x.activation)} / ${Y.isBattle(x.state)?'R'+x.state.round:'探索中'}</small></span></button>`).join('')}<button class="import" data-do="import">＋ キャラシートを読込</button></div></div><div class="sidebar-bottom"><div class="backup-actions"><button data-do="export">バックアップ</button><button data-do="restore-file">復元</button><button data-do="manual">手動作成</button></div><p><span class="local-dot"></span>この端末に自動保存</p><p>キャラのデータはブラウザ内に保存されます。</p><a href="https://wolfuls.github.io/YggRW/index.html" target="_blank" rel="noopener">ユグドラシルRW ルール ↗</a></div></aside><main class="main">${char?`<div class="companion-character"><label>キャラクター<select id="companion-character">${db.characters.map(x=>`<option value="${esc(x.id)}" ${x.id===char.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="small" data-do="import">＋ 読込</button><button class="small" data-do="about">管理</button></div>`+resourceBar(char):''}<div class="topbar"><div class="breadcrumb">YGGDRASILL RW <span>/</span> ${char?'SESSION BOARD':'YOUR SESSION STARTS HERE'}</div><div class="row topbar-actions"><a class="web-download download-nav" href="${WINDOWS_DOWNLOAD}" download="${WINDOWS_FILE}" title="Windows版（64bit、v1.13）をダウンロード">Windows版 ↓</a><span class="status-pill"><span class="local-dot"></span>ブラウザ内に保存</span><button class="ghost small" data-do="about">使い方</button></div></div>${storageError?`<div class="error">${storageError}<button data-do="export-raw">元データを書出</button></div>`:''}${char?board(char):welcome()}</main></div>`;
uiDocument.body.classList.toggle('companion-mode',compactDesktop);if(char&&tab==='compare')calculate();
if(window.chrome?.webview)window.chrome.webview.postMessage('tray:'+tab);
if(window.chrome?.webview)window.chrome.webview.postMessage('resources:'+ (char?'v2|'+['hp','pp','rage','factor','spent','spe','karma'].map(k=>encodeURIComponent(Y.resourceCopy(char,k))).join('|'):'none'));
}
function welcome(){return `<section class="welcome"><div><p class="eyebrow">LESS BOOKKEEPING. MORE ROLEPLAY.</p><h1>次の一手に、<br>集中しよう。</h1><p>キャラシートを読み込んで、セッションを開始。<br>行動の消費、変わり続けるステータス、対抗判定を<br>ひとつのボードで管理します。</p><div class="row wrap"><button class="primary" data-do="import">キャラシートを読み込む ↗</button><button data-do="demo">デモを試す</button><button data-do="restore-file">バックアップから復元</button><button data-do="manual">手動作成</button><a class="web-download download-primary" href="${WINDOWS_DOWNLOAD}" download="${WINDOWS_FILE}">Windows版をダウンロード ↓</a></div><p class="muted-small">対応：RW v0.3pre6.3形式の .xlsx<br>ファイルは端末内で処理されます。</p><p class="web-download download-note">Windows版はZIPを展開して起動できます。<br>HTML版とWindows版の保存データは別々です。バックアップから移せます。</p></div><div class="welcome-art">${symbol}<span class="art-label one">TOTAL PP <b>15</b> → 因子 <b>+3 Rd</b></span><span class="art-label two">あなたの冒険を、この場所に。</span></div></section><section class="welcome-list"><div><small>01 / IMPORT</small><h3>キャラクターを持ち込む</h3><p>ステータスと応用技をExcelから反映。複数キャラもいつでも切り替え。</p></div><div><small>02 / PLAN</small><h3>宣言する前に確かめる</h3><p>消費・活性・バフをまとめて計算。命中の勝率とダメージ期待値も比較。</p></div><div><small>03 / REWIND</small><h3>一手ずつ、記録する</h3><p>行動ごとの状態を保存。過去の記録を残したまま好きな地点に戻る。</p></div></section>`;}
function board(char){const s=char.state;return `<div class="heading"><div><p class="eyebrow">SESSION BOARD</p><h1>${esc(char.name)}</h1><p class="subtle">${esc(char.activation)} <span style="margin:0 8px">·</span> Better Parameter ${Y.bpConfig(s).enabled?'ON':'OFF'}${Y.bpBonuses(char).stunImmune?' · 気絶無効':''}</p></div><div class="row"><button data-do="condition">コンディション</button><button data-do="damage">被ダメージ</button><button data-do="adjust">± 状態を調整</button>${Y.isBattle(s)?`<button class="primary" data-do="next-round">R${s.round+1} へ進む →</button>`:''}</div></div>${s.pending?.length?`<div class="notice"><b>追加処理を確認</b>　${esc(s.pending.join(' / '))}<button class="small" data-do="resolve-pending">処理を記録</button></div>`:''}<nav class="tabs" aria-label="画面切替">${[['actions','行動を組み立てる'],['draft','今回の宣言'],['compare','期待値・勝率'],['buffs','盤面の補正'],['history','行動履歴'],['character','キャラクター']].map(([t,l])=>`<button class="${tab===t?'active':''}" data-do="tab" data-tab="${t}">${l}${t==='history'?`<span class="count">${char.history.length}</span>`:t==='buffs'?`<span class="count">${s.buffs.filter(b=>b.active).length}</span>`:''}</button>`).join('')}</nav><div class="tab-content">${tab==='actions'?actionsView():tab==='draft'?'<div class="draft-expanded">'+progressControls()+draftView()+'</div>':tab==='compare'?compareView():tab==='buffs'?buffView():tab==='history'?historyView():characterView()}</div>`;}
function actionCost(a){
 const unit=a.level?(a.consumable?' / 個':' / Lv'):'',uses=a.owned&&['SPE','カルマ','消費アイテム'].includes(a.group);
 const parts=[];if(a.ppMode==='creation'||a.replace!==undefined)parts.push(Y.costLabel(a));else if(a.pp)parts.push(a.pp+' PP'+unit);if(a.hp)parts.push('HP '+a.hp+unit);if(a.factor)parts.push(a.factor+' Rd'+unit);if(a.rage)parts.push('暴走 +'+a.rage+'%'+unit);
 const cost=a.variableCosts?.length||a.dynamicPP?esc(a.costText||'宣言時に決定'):parts.map(esc).join('・');
 if(uses)return `<b class="remaining-count">${esc(Y.ownedCountLabel(c(),a))}</b><span>${a.consumable?'各1回・使い切り':esc(a.limitText||'回数制限なし')}</span>${cost?'<span class="cost-exception">消費 '+cost+'</span>':''}`;
 return `<b>${cost||'消費なし'}</b>${a.pp&&!a.noRagePP?'<span>暴走 ＋PP消費分</span>':''}`;
}
function optionSummary(a){
 const uses=a.owned&&['SPE','カルマ','消費アイテム'].includes(a.group);
 const summary=uses?Y.ownedCountLabel(c(),a):Y.costLabel(a);
 return a.name+' — '+summary+(!uses&&a.spec?' / SP '+a.spec:'');
}
function actionDetails(a){
 const composition=Array.isArray(a.effects)?a.effects.join(' / '):'';
 let effect=a.note||'';
 if(a.group==='応用技'&&composition&&effect.startsWith(composition))effect=effect.slice(composition.length).replace(/^：/,'').trim();
 const skill=a.explorationSkill?(a.explorationSkill==='能力精度'?c().stats.precision:c().stats.skills[a.explorationSkill]):null;
 return `<div class="selection-detail"><div class="selection-heading"><b>${esc(a.name)}</b>${a.owned?`<button class="ghost small" data-do="inventory-edit" data-id="${esc(a.id)}">編集</button>`:''}</div><div class="selection-meta"><span>${actionCost(a)}</span>${!a.owned&&a.spec?`<span>必要SP ${esc(a.spec)}</span>`:''}${skill!=null?`<span>技能の基礎値 ${esc(skill)}</span>`:''}</div>${composition?`<p><b>技構成</b> ${esc(composition)}</p>`:''}${effect?`<p><b>${a.group==='応用技'?'技効果':'効果・条件'}</b> ${esc(effect)}</p>`:''}</div>`;
}
function progressControls(){const s=c().state,battle=Y.isBattle(s);return `<div class="progress-controls"><div class="mode-switch" role="group" aria-label="進行モード"><button data-do="mode" data-mode="exploration" aria-pressed="${!battle}" class="${!battle?'active':''}">探索中</button><button data-do="mode" data-mode="battle" aria-pressed="${battle}" class="${battle?'active':''}">バトル中</button></div>${battle?`<div class="phase-bar">${Object.entries(Y.phases).filter(([k])=>k!=='EX').map(([k,v])=>`<button class="${s.phase===k?'active':''}" data-do="phase" data-phase="${k}" title="${v}">${k}<span style="display:block;font-size:10px">${v}</span></button>`).join('')}</div>`:''}</div>`;}
function actionsView(){
 const char=c(),state=char.state,battle=Y.isBattle(state);
 const all=[...char.actions,...Y.catalog].filter(a=>Y.phaseAllowed(a,state));
 const actions=all.filter(a=>Y.actionMatches(a,search));
 const groups=[...new Set(['基本行動','応用技','AE','バースト','特殊武装','SPE','カルマ','消費アイテム',...all.map(a=>a.group)])];
 const selected=actions.find(a=>a.id===selectedActionId)||null;
 if(!selected)selectedActionId='';
 const reason=selected?(draft.some(r=>Y.sameAction(r.action,selected))?'追加済み':Y.available(char,selected)):'';
 const options=groups.map(group=>{
  const entries=actions.filter(a=>a.group===group);if(!entries.length)return '';
  return `<optgroup label="${esc(group)}">${entries.map(a=>{const why=draft.some(r=>Y.sameAction(r.action,a))?'追加済み':Y.available(char,a);return `<option value="${esc(a.id)}" ${a.id===selectedActionId?'selected':''}>${esc(optionSummary(a))}${why?'（'+esc(why)+'）':''}</option>`;}).join('')}</optgroup>`;
 }).join('');
 return `<div class="workspace action-workspace"><section class="panel action-panel"><div class="panel-head"><div><h2>${battle?'このラウンドの行動':'探索中の行動'}</h2><p class="subtle">検索で候補を絞り、行動を選んで追加</p></div><span class="tag">${battle?'ROUND '+state.round.toString().padStart(2,'0'):'EXPLORATION'}</span></div>${progressControls()}<div class="action-picker"><label for="action-search">候補を検索<input class="search" id="action-search" type="search" placeholder="技名・効果・分類" value="${esc(search)}"></label><div class="action-picker-row"><label for="action-pick">行動を選択<select id="action-pick"><option value="">${actions.length?'行動を選んでください':'一致する行動がありません'}</option>${options}</select></label><button class="primary action-add" data-do="add-action" data-id="${esc(selectedActionId)}" ${!selected||reason?'disabled':''}>${reason==='追加済み'?'追加済み':'＋ 追加'}</button></div><div class="picker-hint" role="status">${actions.length}件${reason?'　'+esc(reason):''}</div>${selected?actionDetails(selected):''}</div><div class="row wrap inventory-tools"><button class="small" data-do="inventory-import">所持品をExcelから追加</button><button class="small" data-do="inventory-add">＋ 所持品</button><button class="ghost small" data-do="custom-action">＋ カスタム行動</button></div><p class="usage-note">SP＝必要スペック。同じAE・応用技は1つの宣言に1回まで。効果の条件は卓の裁定を確認してください。</p></section>${draftView()}</div>`;
}
function draftView(){const p=Y.preview(c(),draft,desperate);return `<aside class="panel draft"><div class="draft-header"><div class="row between"><h2>今回の宣言 <span class="draft-count">${draft.length.toString().padStart(2,'0')}</span></h2><button class="draft-expand" data-do="tab" data-tab="${tab==='draft'?'actions':'draft'}">${tab==='draft'?'行動一覧へ':'全幅で表示 ↗'}</button></div><p class="subtle">組み合わせと消費を確認してから登録</p></div><div class="draft-body">${draft.length?draft.map((r,i)=>`<div class="draft-row"><div class="row between"><b>${esc(r.action.name)}</b><button class="ghost small" data-do="remove-draft" data-index="${i}" aria-label="${esc(r.action.name)}を外す">×</button></div><p class="muted-small">${esc(r.action.note)}</p><div class="mini-fields">${r.action.ppMode==='creation'?`<label>創造PP（宣言ごとに選択）<select data-draft="creationPP" data-index="${i}" aria-label="${esc(r.action.name)}の創造PP"><option value="">1〜10から選択</option>${Array.from({length:10},(_,n)=>`<option value="${n+1}" ${r.creationPP===n+1?'selected':''}>${n+1} PP</option>`).join('')}</select></label><p class="usage-note">固定追加 ${r.action.pp}PP ＋ 創造 ${r.creationPP??'未選択'}PP${r.creationPP!=null?' ＝ この技の消費 '+Y.declaredPP(r,c().state)+'PP':''}</p>`:''}${r.action.itemTarget?`<label>使用対象<select data-draft="itemTarget" data-index="${i}"><option value="self" ${r.itemTarget!=='other'?'selected':''}>自分（回復を自動反映）</option><option value="other" ${r.itemTarget==='other'?'selected':''}>他者（自身は回復しない）</option></select></label>`:''}${(r.action.variableCosts||[]).map(k=>`<label>今回の${Y.labels[k]}消費${k==='factor'?'（Rd）':''}<input type="number" min="0" data-draft="owned-${k}" data-index="${i}" value="${r['owned-'+k]??''}" placeholder="0以上"></label>`).join('')}${r.action.level?`<label>${r.action.consumable?'使用個数':'Lv'}<input type="number" data-draft="level" data-index="${i}" min="1" max="${r.action.max||100}" value="${r.level}"></label>`:''}${r.action.targets?`<label>補正先<select data-draft="target" data-index="${i}">${r.action.targets.map(t=>`<option value="${t}" ${r.target===t?'selected':''}>${Y.labels[t]||({damage:'ダメージ',skill:'技能・解除'})[t]}</option>`).join('')}</select></label>`:''}${r.action.roll&&r.itemTarget!=='other'?`<label>${r.action.rollDice*r.level}D6の出目<input type="number" data-draft="result" data-index="${i}" value="${r.result??''}" min="${r.action.rollDice*r.level}" max="${6*r.action.rollDice*r.level}" placeholder="実際の合計"></label><button class="small" data-do="roll" data-index="${i}" title="ランダムな実際の出目を入力">振る</button>`:''}</div></div>`).join(''):'<div class="empty-draft"><span class="plus">＋</span>行動一覧から行動を選ぶと、<br>ここで組み合わせを確認できます。</div>'}<div class="mini-fields" style="margin-top:15px"><label>死力 Lv（HPでPPを代用）<input type="number" id="desperate" min="0" value="${desperate}"></label></div><div class="draft-totals"><div><span>HP消費</span><b>−${p.hp}</b></div><div><span>PP消費</span><b>−${p.pp}</b></div><div><span>因子消費</span><b>−${p.factor} Rd</b></div><div><span>暴走率</span><b>${p.rage>=0?'+':''}${p.rage}%</b></div><div><span>総消費PP</span><b>+${p.spent}</b></div><div><span>回復 HP / PP</span><b>+${p.rhp} / +${p.rpp}</b></div></div><div class="gain"><span>総消費PPによる因子獲得</span><b>+${p.gained} Rd</b></div>${draft.length?`<div class="next-state">登録後　HP ${p.after.hp} / PP ${p.after.pp}<br>暴走 ${p.after.rage}% / 因子 ${p.after.factor} Rd</div>`:''}${draft.length&&p.errors.length?`<div class="error">${p.errors.map(esc).join('<br>')}</div>`:''}${draft.length&&p.warnings.length?`<div class="warning">${p.warnings.map(esc).join('<br>')}</div>`:''}<label style="margin-top:15px">行動メモ<textarea id="action-note" placeholder="対象・宣言・判定結果など">${esc(note)}</textarea></label></div><div class="draft-footer"><button class="primary full" data-do="commit" ${!draft.length||p.errors.length?'disabled':''}>この宣言を登録　→</button><p class="subtle">登録した状態は、履歴から巻き戻せます。</p></div></aside>`;}
function compareView(){const char=c(),o=char.state.opponent;return `<div class="panel"><div class="panel-head"><div><h2>対抗判定を比較する</h2><p class="subtle">勝率は、1回の命中・回避対抗に勝つ確率です。</p></div><span class="tag">バフ・活性を反映</span></div><div class="compare-choices">${select('compare-attack','攻撃力',compareOpts.attack,[['melee','格闘'],['weapon','武器'],['power','能力']])}${select('compare-mental','判定',compareOpts.mental?'ss':'physical',[['physical','命中 対 回避'],['ss','SS 対 SS（精神）']])}</div><div class="compare-grid"><section><h3>${esc(char.name)}</h3><div class="form-grid two">${input('compare-ownFixed','命中の追加固定値',compareOpts.ownFixed||0)}${input('compare-ownDice','命中の追加ダイス',compareOpts.ownDice||0)}</div><label class="checkbox" style="margin-top:14px"><input type="checkbox" name="compare-includeDraft" ${compareOpts.includeDraft?'checked':''}>今回の宣言のコンセ・ブースト等を反映</label><p class="usage-note" id="effective-own"></p></section><section><div class="row between"><h3>比較する相手</h3><button class="small ghost" data-do="opponent-from-character">保存キャラから反映</button></div><div class="form-grid two">${input('enemy-name','相手の名前',o.name,'text')}${input('enemy-hp','相手HP',o.hp)}${input('enemy-fixed',compareOpts.mental?'相手のSS固定値':'相手の回避固定値',o.fixed)}${input('enemy-dice','相手の判定ダイス',o.dice,'number','min="0" max="20"')}${input('enemy-defense','相手の防御力',o.defense)}${input('enemy-resist','相手の抵抗力',o.resist)}${select('enemy-activation','相手の活性タイプ',o.activation||'－',['－','覚醒型','増強型','反応型','感覚型','回復型'])}${input('enemy-rage','相手の暴走率',o.rage||0,'number','min="0"')}</div><p class="usage-note">相手の判定値はBP・活性を含めた値を入力。防御力に増強型の補正は加算せず、活性タイプと暴走率から被ダメージ軽減を別途計算します。盤面の「相手」補正も加算します。</p></section></div><label class="checkbox" style="margin-top:14px"><input type="checkbox" name="compare-ignoreArmor" ${compareOpts.ignoreArmor?'checked':''}>装甲無視（増強型の軽減は適用）</label><div id="comparison-results"></div><details class="about"><summary>計算条件と詳細</summary><div class="form-grid" style="margin:15px 0">${select('compare-mode','判定ダイス',compareOpts.mode,[['cf','クリティカル・ファンブルあり'],['normal','通常のD6（特殊処理なし）']])}${select('compare-tie','同値の場合',compareOpts.tie,[['reroll','同値ロール（勝率50%）'],['attacker','攻撃側優先'],['defender','防御側優先']])}${select('compare-minimum','装甲適用後の下限',compareOpts.minimum,[[0,'0ダメージ'],[1,'1ダメージ']])}</div><p>最初の6は連続する限り追加、最初の1は1D6減算。最終達成値の下限は1です。ダメージは通常D6で、倍差命中とスマッシュクリティカルを含みます。勝率・期待値は分布計算で求めています（極小の無限尾部のみ打切り）。</p><p>1回の対抗判定・単体への1ヒットが対象です。戦闘全体の勝利確率、幸運系・特殊な出目操作、多段攻撃、トラップ等の独自処理は含みません。増強型はダメージ判定を軽減（下限1）、その後に装甲を適用します。装甲適用後の下限は卓に合わせて変更できます。</p></details></div>`;}
function calculate(){try{const char=c(),k=compareOpts.mental?'ss':'hit',own=Y.effective(char,k),atk=Y.effective(char,compareOpts.attack),o=char.state.opponent;own.fixed+=Number(compareOpts.ownFixed||0);own.dice+=Number(compareOpts.ownDice||0);let half=false;
 if(compareOpts.includeDraft){for(const r of draft){const a=r.action;if(a.id==='con'&&(r.target===k||r.target==='hit'&&k==='ss'))own.fixed+=r.level;if(['boost','checkB'].includes(a.id)&&(r.target===k||r.target==='hit'&&k==='ss'))own.dice+=r.level;if(a.id==='con'&&r.target==='damage')atk.fixed+=r.level;if(a.id==='mercy'||a.id==='squeeze')half=true;}if(draft.some(r=>r.action.id==='head')){own.fixed=Math.floor(own.fixed/2);atk.dice++;}const replace=draft.find(r=>r.action.replace!==undefined);if(replace)own.fixed=char.stats.params[replace.action.replace];}
 const em=Y.modifiers(char,compareOpts.mental?'ss':'dodge','enemy'),am=Y.modifiers(char,compareOpts.mental?'resist':'defense','enemy');const ef=Math.floor((o.fixed+em.flat)*em.mult),ed=Math.max(0,o.dice+em.dice),armor=compareOpts.ignoreArmor?0:Math.floor(((compareOpts.mental?o.resist:o.defense)+am.flat)*am.mult),reduction=Y.damageReduction({activation:o.activation,state:{rage:o.rage||0}});
 if(atk.dice<0||atk.dice>30)throw Error('ダメージダイスは0〜30の範囲にしてください');
 const result=Y.compare({ownFixed:own.fixed,ownDice:own.dice,enemyFixed:ef,enemyDice:ed,damageDice:atk.dice,damageFlat:atk.fixed,armor,reduction,mode:compareOpts.mode,tie:compareOpts.tie,half,minimum:Number(compareOpts.minimum)});calcResult=result;
 $('#effective-own').textContent=`反映後：${own.fixed} + ${own.dice}D6　威力 ${atk.dice}D6 + ${atk.fixed} ／ 相手 ${ef} + ${ed}D6・装甲 ${armor}・増強軽減 ${reduction}`;
 const vals=[...result.own.keys(),...result.enemy.keys()].sort((a,b)=>a-b),lower=Math.max(1,Math.floor(Math.min(result.ownMean,result.enemyMean)-12)),upper=Math.ceil(Math.max(result.ownMean,result.enemyMean)+20),bins=Math.min(35,upper-lower+1),step=Math.ceil((upper-lower+1)/bins);let bars=[];for(let i=lower;i<=upper;i+=step){let a=0,b=0;for(let j=i;j<i+step;j++){a+=result.own.get(j)||0;b+=result.enemy.get(j)||0;}bars.push({x:i,a,b});}const peak=Math.max(...bars.flatMap(b=>[b.a,b.b]),.01);
 $('#comparison-results').innerHTML=`<div class="result-grid"><div class="result primary-result"><div class="result-label">対抗判定の勝率</div><div class="result-number">${(result.win*100).toFixed(1)}<small>%</small></div><div class="result-caption">同値 ${(result.equal*100).toFixed(1)}% ／ 倍差命中 ${(result.double*100).toFixed(1)}%</div></div><div class="result"><div class="result-label">期待ダメージ</div><div class="result-number">${result.win>0?result.onHit.toFixed(1):'—'}<small>点</small></div><div class="result-caption">${result.win>0?'命中時の平均／装甲・増強軽減・倍差込み':'命中率0%のため算出対象外'}</div></div><div class="result"><div class="result-label">達成値の期待値</div><div class="result-number">${result.ownMean.toFixed(2)}</div><div class="result-caption">相手 ${result.enemyMean.toFixed(2)} ／ 差 ${(result.ownMean-result.enemyMean).toFixed(2)}</div></div></div><details class="distribution"><summary>達成値の分布</summary><div class="row between"><h3>達成値の分布</h3><div class="legend"><span><i></i>自分</span><span><i class="enemy"></i>相手</span></div></div><div class="chart-wrap"><div class="chart" role="img" aria-label="自分と相手の達成値の確率分布">${bars.map((b,i)=>`<div class="chart-col" title="達成値${b.x}${step>1?'〜'+(b.x+step-1):''}：自分${(b.a*100).toFixed(2)}%、相手${(b.b*100).toFixed(2)}%"><i style="height:${b.a/peak*100}%"></i><i class="enemy" style="height:${b.b/peak*100}%"></i>${i%5===0?`<span>${b.x}</span>`:''}</div>`).join('')}</div></div><p class="muted-small">グラフは分布の中心部分を表示。確率計算は表示範囲外も含みます。</p></details>`;
 }catch(e){$('#comparison-results').innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
function buffView(){const char=c();return `<div class="panel"><div class="panel-head"><div><h2>盤面のバフ・デバフ</h2><p class="subtle">名前、対象、補正値を登録。チェックを外すと一時的に無効になります。</p></div><button class="primary" data-do="add-buff">＋ 補正を追加</button></div>${char.state.buffs.length?char.state.buffs.map(b=>`<div class="buff-row ${b.active===false?'inactive':''}"><input type="checkbox" data-buff-toggle="${esc(b.id)}" ${b.active!==false?'checked':''} aria-label="${esc(b.name)}の有効切替"><div><b>${esc(b.name)}</b><small>${({self:'自分',enemy:'相手',both:'両者'})[b.target]} / ${Y.labels[b.stat]||({damage:'ダメージ',skill:'技能・解除',allChecks:'すべての判定'})[b.stat]||esc(b.stat)}${b.endRound?' / R'+b.endRound+'まで':''}</small></div><div class="buff-mod">${b.flat>=0?'+':''}${b.flat}${b.dice?' / '+(b.dice>0?'+':'')+b.dice+'D6':''}${b.mult!==1?' / ×'+b.mult:''}</div><button class="small" data-do="edit-buff" data-id="${esc(b.id)}">編集</button></div>`).join(''):'<div class="empty">盤面の補正はまだありません。<br>味方からの支援や、相手のデバフを追加できます。</div>'}<p class="usage-note">同じステータスへの固定値・ダイス補正は加算、倍率は乗算して最後に切り捨てます。上書きルールで重ならない効果は、片方を無効にしてください。</p></div>`;}
function historyView(){const char=c();return `<div class="panel-head"><div><h2>行動履歴</h2><p class="subtle">巻き戻しもひとつの履歴として残ります。元の記録は消えません。</p></div><div class="row"><button class="small" data-do="export-history">CSV書出</button><button class="small" data-do="rollback" data-id="initial">読込時へ戻る</button></div></div>${[...char.history].reverse().map(e=>`<article class="history-entry"><header><div><div class="history-meta">${e.phase==='EX'?'探索中':'ROUND '+e.round+' / '+(Y.phases[e.phase]||e.phase)}　${new Date(e.time).toLocaleString('ja-JP')}</div><h3>${esc(e.title)}</h3></div><button class="small" data-do="rollback" data-id="${esc(e.id)}">この時点へ戻る</button></header><div class="history-chips">${['hp','pp','rage','factor','spent'].map(k=>`<span>${Y.labels[k]} ${e.before[k]} → <b>${e.after[k]}</b></span>`).join('')}</div>${e.detail?.rows?.some(r=>r.action.ppMode==='creation')?`<p class="usage-note">${e.detail.rows.filter(r=>r.action.ppMode==='creation').map(r=>esc(r.action.name)+'：創造 '+r.creationPP+'PP ＋ 固定追加 '+r.action.pp+'PP ＝ '+r.declaredPP+'PP').join('<br>')}</p>`:''}${e.detail?.spent!==undefined?`<p class="usage-note">消費PP ${e.detail.pp} / 総消費加算 ${e.detail.spent} / 獲得因子 +${e.detail.gained} Rd${e.detail.desperate?' / 死力 Lv'+e.detail.desperate:''}</p>`:''}${e.type==='damage'?`<p class="usage-note">判定 ${e.detail.raw} ／ 増強軽減 ${e.detail.reduction} ／ 装甲 ${e.detail.armor} → 被ダメージ ${e.detail.damage}</p>`:''}${e.detail?.note?`<p class="usage-note">${esc(e.detail.note)}</p>`:''}<details><summary>補正・相手を含む状態を見る</summary><pre>${esc(JSON.stringify(e.after,null,2))}</pre></details></article>`).join('')||'<div class="panel empty">登録した行動がここに並びます。</div>'}`;}
function characterView(){const char=c();return `<div class="panel"><div class="panel-head"><div><h2>キャラクター設定</h2><p class="subtle">読込元：${esc(char.source)}${char.importedAt?' / '+new Date(char.importedAt).toLocaleDateString('ja-JP'):''}</p></div><button data-do="edit-character">基礎ステータスを編集</button></div><div class="stats-grid">${['hit','dodge','ss','melee','weapon','power','defense','resist','initiative','precision','spec'].map(k=>{const v=Y.effective(char,k);return `<div class="stat">${Y.labels[k]}<strong>${['melee','weapon','power'].includes(k)?v.dice+'D6 + '+v.fixed:['hit','dodge','ss'].includes(k)?v.fixed+' + '+v.dice+'D6':v.fixed}</strong></div>`}).join('')}</div><p class="usage-note">上記はBP・活性・盤面の補正を反映した値です。SSの補正は命中・回避判定用です。増強型の被ダメージ軽減：${Y.damageReduction(char)}点（装甲無視にも適用）。</p><div class="notice"><b>Better Parameter ${Y.bpConfig(char.state).enabled?'ON':'OFF'}</b><p class="usage-note">${bpSummary(char)}</p></div><hr class="section-divider"><div class="panel-head"><h3>応用技・カスタム行動</h3><button class="small" data-do="custom-action">＋ 登録</button></div>${char.actions.filter(a=>!a.owned).map(a=>`<div class="buff-row"><span class="tag">技</span><div><b>${esc(a.name)}</b><small>${esc(a.note)}</small></div><div class="buff-mod">${Y.costLabel(a)}${a.spec?' / '+a.spec+' spec':''}</div><button class="small" data-do="edit-action" data-id="${esc(a.id)}">編集</button></div>`).join('')||'<p class="subtle">応用技が未登録です。Excelから読み込むか、手動で登録できます。</p>'}<hr class="section-divider">${inventorySection()}<hr class="section-divider"><div class="row wrap"><button data-do="import">別のキャラシートを読込</button><button data-do="export">全データをバックアップ</button><button data-do="restore-file">バックアップを復元</button><button class="danger" data-do="delete-character">このキャラを削除</button></div></div>`;}
function importDialog(){modal('キャラシートを読み込む',`<p class="subtle" style="margin-bottom:18px">Excelに保存されたステータス・応用技を取り込み、キャラクターとして保存します。</p>${select('import-mode','開始する状態',importMode,[['progress','進行表の現在値を引き継ぐ'],['base','キャラシートの基礎値から開始']])}<p class="usage-note">対応形式：characterheet_RW_v0.3pre6.3.xlsxと同じセル配置。数式はExcelの保存済み計算結果を使います。取り込み前にExcelで再計算して保存してください。</p><div class="form-actions"><button data-do="manual">手動で作成</button><button class="primary" data-do="choose-xlsx">.xlsx ファイルを選ぶ</button></div>`);}
function importReview(char){const missing=char.actions.flatMap((a,i)=>(a.importMissing||[]).map(m=>({a,i,m})));if(!missing.length)return '';return `<hr class="section-divider"><h3>応用技の数値を確認</h3><div class="warning">ステータスは読み込めています。次の欄だけ数値を取得できませんでした。技の消費・スペックを入力すると保存できます。</div><div class="form-grid two">${missing.map(({a,i,m})=>input('import-action-'+i+'-'+m.field,esc(a.name)+'：'+(m.field==='pp'?(a.ppMode==='creation'?'固定追加PP（創造1〜10PPを除く）':'消費PP'):'必要スペック')+'（'+esc(m.cell)+'）','','number','min="0" required')+`<p class="usage-note">Excel内の値：${esc(m.raw===''?'未保存・空欄':m.raw)}</p>`).join('')}</div>`;}
function characterDialog(char,isNew=false){pendingImport=isNew?char:null;const s=char.stats;modal(isNew?'読み込み内容を確認':'基礎ステータスを編集',`<form id="character-form"><div class="form-grid">${input('name','キャラクター名',char.name,'text','required')}${select('activation','活性タイプ',char.activation,['－','覚醒型','増強型','反応型','感覚型','回復型'])}${input('hpMax','基礎最大HP',s.hpMax,'number','min="1" required')}${input('ppMax','基礎最大PP',s.ppMax,'number','min="0" required')}${input('initiative','行動値',s.initiative)}${['hit','dodge','ss'].map(k=>input(k,Y.labels[k]+'固定値',s[k])+input(k+'Dice',Y.labels[k]+'ダイス',s[k+'Dice'],'number','min="0" max="20"')).join('')}${['melee','weapon','power'].map(k=>input(k,Y.labels[k]+'ダイス',s[k],'number','min="0" max="30"')+input(k+'Flat',Y.labels[k]+'固定値',s[k+'Flat'])).join('')}${['defense','resist','precision','spec'].map(k=>input(k,Y.labels[k],s[k])).join('')}</div>${bpFields(char)}<details style="margin-top:18px"><summary>パラメータ・技能</summary><div class="form-grid four" style="margin-top:12px">${['筋力','耐久','知力','精神','器用','敏捷','運'].map((x,i)=>input('param'+i,x,s.params[i])).join('')}${Y.skillNames.map(x=>input('skill-'+x,x,s.skills[x]||0)).join('')}</div></details>${isNew?`<hr class="section-divider"><h3>引き継ぐ現在値</h3><div class="form-grid">${['hp','pp','rage','factor','spent','hpMax','ppMax'].map(k=>input('state-'+k,k==='hpMax'?'セッション最大HP':k==='ppMax'?'セッション最大PP':Y.labels[k],char.state[k])).join('')}</div>${importReview(char)}<p class="usage-note">応用技 ${char.actions.length}件を読み込みました。既存キャラは上書きせず、新しいキャラとして追加します。</p>`:'<p class="usage-note">現在HP・PPは「状態を調整」で変更できます。基礎設定の編集は過去の状態スナップショットには影響しません。</p>'}<p class="usage-note">反応型はSSを用いる命中・回避判定にも加算。感覚型は行動値に加算。増強型は防御力を増やさず、「被ダメージ」と期待ダメージで軽減します。</p><div class="form-actions"><button type="button" data-do="close">キャンセル</button><button class="primary" type="submit">${isNew?'このキャラを保存':'設定を保存'}</button></div></form>`,esc(char.source));}

function readBPForm(form){const d=new FormData(form),b=Y.bpConfig((pendingImport||c()).state);b.enabled=d.get('bp-enabled')==='yes';for(const k of ['hit','dodge','initiative','melee','weapon','power','defense','pp']){const v=d.get('bp-'+k+'Included');b[k+'Included']=v==='unknown'?null:v==='yes';}b.statsIncluded=['hit','dodge','initiative'].every(k=>b[k+'Included']===true);b.damageIncluded=['melee','weapon','power'].every(k=>b[k+'Included']===true);return b;}
function bpSummary(char){const b=Y.bpBonuses(char),sign=n=>(n>=0?'+':'')+n;const attack=b.meleeDice===b.weaponDice&&b.meleeDice===b.powerDice?`攻撃 ${sign(b.meleeDice)}D6`:`格闘 ${sign(b.meleeDice)}D6／武器 ${sign(b.weaponDice)}D6／能力 ${sign(b.powerDice)}D6`;return `入力値への差分：命中 ${sign(b.hit)}／回避 ${sign(b.dodge)}／行動値 ${sign(b.initiative)}／${attack}／防御 ${sign(b.defense)}／最大PP ${sign(b.ppMax)}。${b.stunImmune?'耐久18以上：気絶無効。':''}`;}
function bpFields(char){const b=Y.bpConfig(char.state),det=char.bpDetection;
 const fields=[['hit','命中のBP補正'],['dodge','回避のBP補正'],['initiative','行動値のBP補正'],['melee','格闘のBP＋1D6'],['weapon','武器のBP＋1D6'],['power','能力のBP＋1D6'],['defense','筋力18以上の防御＋1'],['pp','耐久18以上のPP＋3']];
 const included=k=>['defense','pp'].includes(k)?b[k+'Included']:Y.bpIncluded(b,k),unknown=fields.filter(([k])=>included(k)===null).map(([,label])=>label);
 return `<section class="bp-settings"><div class="row between"><h3>Better Parameter</h3>${select('bp-enabled','このキャラで採用',b.enabled?'yes':'no',[['yes','ON'],['no','OFF']])}</div><p class="usage-note">${det?'シートから自動判定しました。BP設定・基礎値・特化補正・攻撃の取得点を照合しています。':'保存済みの設定を使用します。Excelを読み込むと補正を自動判定します。'}通常はそのまま保存できます。</p>${unknown.length?`<p class="warning">判定できない項目：${esc(unknown.join('、'))}。入力値を保持し、これらの項目にはBP差分を加減算しません。必要な場合のみ詳細設定で変更できます。</p>`:''}<details><summary>自動判定の内訳・詳細設定（通常は変更不要）</summary><p class="usage-note">${det?'シートのBP設定：'+esc(det.flag)+'。':'既存の設定・手動入力値です。'}採用ON／OFFを切り替えても、入力済みの数値は保持して差分だけ反映します。</p><div class="form-grid two">${fields.map(([k,label])=>select('bp-'+k+'Included',label,included(k)===null?'unknown':included(k)?'yes':'no',[['yes','入力値に反映済み'],['no','入力値に含まない'],['unknown','判定保留（入力値を保持）']])).join('')}</div>${det?`<ul class="usage-note">${det.items.map(i=>`<li>${esc(i.label)}：${esc(i.reason)}</li>`).join('')}</ul>`:''}<p class="usage-note">防御＋1・PP＋3はシートの特化補正と重複させません。PP補正の追加・解除時は残PPと最大PPを同量調整します。由来の分からない手入力は自動加算せず、設定を保存して次回も使います。</p></details><p class="notice" id="bp-preview">${bpSummary(char)}</p></section>`;}
function updateBPPreview(){const form=$('#character-form'),out=$('#bp-preview');if(!form||!out)return;const char=Y.clone(pendingImport||c()),d=new FormData(form);char.state.bp=readBPForm(form);char.stats.params=char.stats.params.map((_,i)=>Number(d.get('param'+i)));out.textContent=bpSummary(char);}
function damageDialog(){modal('被ダメージを登録',`<form id="damage-form"><p class="subtle">装甲と増強型の軽減を適用する前の、確定したダメージ判定値を入力します。</p><div class="form-grid two">${input('damageRaw','ダメージ判定値',0,'number','min="0" required')}${select('damageKind','ダメージ種別','physical',[['physical','物理（防御を適用）'],['mental','精神（抵抗を適用）'],['ignore','装甲無視']])}${input('damageNote','メモ','','text')}</div><div class="notice" id="damage-preview"></div><p class="usage-note">増強型はダメージ判定を減算（下限1）、その後に装甲を適用します。最終ダメージは0以上。死力・技のHP消費やHP直接調整には適用しません。</p><div class="form-actions"><button type="button" data-do="close">キャンセル</button><button class="primary">被ダメージを履歴に登録</button></div></form>`);updateDamagePreview();}
function updateDamagePreview(){const f=$('#damage-form');if(!f)return;try{const d=new FormData(f),r=Y.damageTaken(c(),Number(d.get('damageRaw')),d.get('damageKind'));$('#damage-preview').textContent=`判定 ${r.raw} ／ 増強軽減 ${r.reduction} ／ 装甲 ${r.armor} → 被ダメージ ${r.damage}　HP ${c().state.hp} → ${r.afterHP}`;}catch(e){$('#damage-preview').textContent=e.message;}}

function adjustDialog(resolve=false){const s=c().state;modal(resolve?'追加処理を記録':'状態を調整',`<form id="adjust-form" data-resolve="${resolve}"><p class="subtle" style="margin-bottom:18px">回復・シーンチェック・臨界因子など、実際の増減を入力します。攻撃を受ける場合は「被ダメージ」で装甲・増強軽減を計算できます。</p><div class="form-grid">${input('hp','HP増減',0)}${input('pp','PP増減（回復・直接増減）',0)}${input('rage','暴走率増減',0)}${input('factor','因子増減（Rd）',0)}${input('costPP','消費PP（総消費と暴走に加算）',0,'number','min="0"')}${input('hpMax','セッション最大HP',s.hpMax,'number','min="1"')}${input('ppMax','セッション最大PP',s.ppMax,'number','min="0"')}${input('reason','メモ',resolve?s.pending.join(' / '):'状態調整','text','required')}</div><p class="usage-note">この画面のHP直接増減には装甲・増強軽減を適用しません。「PP増減」は総消費PP・暴走率を変更しません。PPを消費する場合は「消費PP」を使います。HP/PPの回復はセッション最大値で止まります。</p>${resolve?'<p class="warning">暴走・臨界ロール、回復型の活性回復、臨界域の因子獲得は実際の結果を入力してください。</p>':''}<div class="form-actions"><button type="button" data-do="close">キャンセル</button><button class="primary">調整を履歴に登録</button></div></form>`);}
function buffDialog(b){b=b||{id:Y.id(),name:'',target:'self',stat:'hit',flat:0,dice:0,mult:1,active:true,endRound:''};modal('盤面の補正を登録',`<form id="buff-form" data-id="${esc(b.id)}"><div class="form-grid two">${input('name','バフ・デバフ名',b.name,'text','required')}${select('target','対象',b.target,[['self','自分'],['enemy','相手'],['both','両者']])}${select('stat','補正するステータス',b.stat,[...['hit','dodge','ss','defense','resist','initiative','precision','spec'].map(k=>[k,Y.labels[k]]),['damage','全攻撃のダメージ'],['melee','格闘ダメージ'],['weapon','武器ダメージ'],['power','能力ダメージ'],['allChecks','命中・回避・SS・技能'],['skill','技能・解除']])}${input('flat','固定値の増減',b.flat)}${input('dice','ダイスの増減',b.dice)}${select('mult','固定値の倍率',b.mult,[[1,'×1（変更なし）'],[.5,'×0.5'],[2,'×2'],[0,'×0']])}${input('endRound','有効な最終ラウンド（空欄＝継続）',b.endRound,'number','min="1"')}<label class="checkbox"><input type="checkbox" name="active" ${b.active?'checked':''}>有効</label></div><div class="form-actions">${c().state.buffs.some(x=>x.id===b.id)?`<button type="button" class="danger" data-do="delete-buff" data-id="${b.id}">削除</button>`:''}<button type="button" data-do="close">キャンセル</button><button class="primary">補正を保存</button></div></form>`);}
let editingOwned=null;
function randomDice(count){let sum=0;for(let i=0;i<count;i++){const v=new Uint32Array(1);do{crypto.getRandomValues(v);}while(v[0]>=4294967292);sum+=v[0]%6+1;}return sum;}
async function copyResource(key){
 const text=Y.resourceCopy(c(),key),doc=uiDocument;
 if(!text)return;
 if(window.chrome?.webview){window.chrome.webview.postMessage('copy:'+encodeURIComponent(text));return;}
 try{await doc.defaultView.navigator.clipboard.writeText(text);withSurface(doc,()=>toast('コピーしました：'+text));}
 catch(e){withSurface(doc,()=>modal('コピーする内容',`<textarea id="copy-value" readonly>${esc(text)}</textarea><p class="usage-note">コピーが許可されていない場合は、選択された内容をCtrl+Cでコピーしてください。</p>`));doc.querySelector('#copy-value').select();}
}
function inventorySection(){return `<div class="panel-head"><h3>所持する特殊武装・SPE・カルマ・消費アイテム</h3><div class="row wrap"><button data-do="inventory-import">Excelから追加</button><button data-do="inventory-add">＋ 登録</button></div></div>${c().actions.filter(a=>a.owned).map(a=>`<div class="buff-row"><span class="tag">${esc(a.group)}</span><div><b>${esc(a.name)}</b><small>${esc(Y.ownedCountLabel(c(),a))}${a.consumable?'（各1回）':''}${a.needsReview?'・要確認':''}</small></div><button class="small" data-do="inventory-edit" data-id="${a.id}">編集</button></div>`).join('')||'<p class="subtle">キャラシートから読み込むか、所持しているものを登録してください。</p>'}`;}
function inventoryDialog(a){
 editingOwned=a?Y.clone(a):{id:Y.id(),name:'',group:'消費アイテム',owned:true,pp:0,hp:0,factor:0,rage:0,spec:0,quantity:1,phases:['IN','AC','RE','EN','EX'],manualEffect:true};const x=editingOwned;
 modal('所持品を登録・編集',`<form id="inventory-form"><label>ルールから選ぶ<select name="owned-preset"><option value="">名称・効果を手動で設定</option>${Y.ownedGroups.map(g=>`<optgroup label="${g}">${Y.ownedCatalog.filter(v=>v.group===g).map(v=>`<option value="${v.catalogKey}" ${v.catalogKey===x.catalogKey?'selected':''}>${esc(v.name)}</option>`).join('')}</optgroup>`).join('')}</select></label><div class="form-grid" style="margin-top:16px">${input('name','名前',x.name,'text','required')}${select('group','分類',x.group,Y.ownedGroups)}${input('quantity','所持数（武装のHPボーナス計算にも使用）',x.quantity??1,'number','min="0" max="99" required')}${input('remaining','残数 / 残り使用回数',c().actions.some(a=>a.id===x.id)?Y.ownedRemaining(c(),x)??0:x.consumable?x.quantity??1:x.useLimit||0,'number','min="0" max="999" required')}${input('useLimit','使用回数の上限（0＝無制限）',x.useLimit||0,'number','min="0" max="999"')}${select('usePeriod','使用回数の区切り',x.usePeriod||'session',[['session','セッション'],['battle','バトル'],['round','ラウンド']])}${input('pressure','特殊武装の圧迫SP',x.pressure??'','number','min="0" max="100"')}${input('pp','固定のPP消費',x.pp||0,'number','min="0"')}${input('hp','固定のHP消費',x.hp||0,'number','min="0"')}${input('factor','因子消費（Rd）',x.factor||0,'number','min="0"')}${input('rage','追加の暴走率上昇',x.rage||0,'number','min="0"')}<label class="checkbox"><input name="passive" type="checkbox" ${x.passive?'checked':''}>常時効果（宣言不要）</label><label class="checkbox"><input name="main" type="checkbox" ${x.main?'checked':''}>メイン行動を使用</label><div class="span-all"><label>宣言できるフェイズ</label><div class="row wrap">${Object.keys(Y.phases).map(k=>`<label class="checkbox"><input type="checkbox" name="phase-${k}" ${x.phases.includes(k)?'checked':''}>${k}</label>`).join('')}</div></div><label class="span-all">効果・条件<textarea name="note" rows="6">${esc(x.note||'')}</textarea></label></div><p class="usage-note">消費アイテムの価格は購入時の因子です。使用時には残数だけを減らします。回数無制限では「残り使用回数」は使いません。常時効果や圧迫SPを、読み込んだ基礎ステータスに再加算しません。${x.variableCosts?.length||x.dynamicPP?'この効果の変動コストは宣言時に決定します。':''}</p>${/^https:\/\/wolfuls\.github\.io\/YggRW\//.test(x.ruleUrl||'')?`<a href="${esc(x.ruleUrl)}" target="_blank" rel="noopener">ルールの詳細 ↗</a>`:''}<div class="form-actions">${c().actions.some(a=>a.id===x.id)?`<button type="button" class="danger" data-do="delete-action" data-id="${x.id}">削除</button>`:''}<button type="button" data-do="close">キャンセル</button><button class="primary">この内容で登録</button></div></form>`);
}
function conditionDialog(){
 const char=c(),old=char.state.condition,bonus=old?.weaponBonus??Y.weaponBonus(char),hp=old?.hpRoll??(old?old.hp-bonus:''),pp=old?.ppRoll??old?.pp??'',maximum=char.actions.find(a=>a.conditionItem&&Y.ownedRemaining(char,a)>0),unknown=char.actions.filter(a=>a.owned&&a.group==='特殊武装'&&a.pressure==null);
 modal('コンディションロール',`<form id="condition-form"><p class="subtle">HP・PPにそれぞれ2D6を加算し、PPの上昇分だけ暴走率も上げます。HPには特殊武装の圧迫SP×3を加えます。</p>${old?`<div class="notice">登録済み：HP +${old.hp} / PP +${old.pp}。${old.source==='sheet'?'進行表のコンディションを読み込みました。':old.source==='maxima'?'進行表の最大値と基礎値の差を反映済みとして扱っています。':''}今回の値との差分だけ反映します。</div>`:''}<div class="form-grid condition-fields">${input('hpRoll','HP：2D6の合計',hp,'number','min="2" max="12" required')}<button type="button" data-do="condition-roll" data-field="hpRoll">HPの2D6を振る</button>${input('ppRoll','PP：2D6の合計',pp,'number','min="2" max="12" required')}<button type="button" data-do="condition-roll" data-field="ppRoll">PPの2D6を振る</button>${input('bonus','特殊武装によるHPボーナス',bonus,'number','min="0" max="300" required')}${old?select('reroll','今回の処理','yes',[['yes','振り直し（1 Rd消費）'],['no','入力内容の訂正（振り直しではない）']]):'<input name="reroll" type="hidden" value="no">'}${!old&&maximum?`<label class="checkbox span-all"><input name="maximumId" type="checkbox" value="${maximum.id}">マキシマムを1個使用（HP・PPの出目を10に固定）</label>`:''}</div>${unknown.length?`<p class="warning">圧迫SP未確認：${unknown.map(a=>esc(a.name)).join('、')}。HPボーナスを確認してください。</p>`:''}<div id="condition-preview" class="notice"></div><p class="usage-note">HP・PPの現在値と最大値を同じ差分で更新し、既に受けたダメージやPP消費を保持します。コンディションのPP上昇は総消費PPに加算しません。登録した内容は履歴から巻き戻せます。</p><div class="form-actions"><button type="button" data-do="close">キャンセル</button><button class="primary">コンディションを反映</button></div></form>`);updateConditionPreview();
}
function conditionValues(form){const d=new FormData(form),maximumId=d.get('maximumId');return {hpRoll:maximumId?10:Number(d.get('hpRoll')),ppRoll:maximumId?10:Number(d.get('ppRoll')),bonus:Number(d.get('bonus')),reroll:d.get('reroll')==='yes',maximumId};}
function updateConditionPreview(){const f=$('#condition-form');if(!f)return;const maximum=f.elements.maximumId?.checked;for(const k of ['hpRoll','ppRoll']){f.elements[k].required=!maximum;if(maximum)f.elements[k].value=10;}try{const copy=Y.clone(c());Y.applyCondition(copy,conditionValues(f));const s=copy.state;$('#condition-preview').textContent=`反映後：HP ${s.hp} / ${s.hpMax}、PP ${s.pp} / ${s.ppMax}、暴走率 ${s.rage}%、因子 ${s.factor} Rd`;}catch(e){$('#condition-preview').textContent=e.message;}}

function customDialog(a){a=a||{id:Y.id(),name:'',pp:0,hp:0,factor:0,rage:0,spec:0,note:'',group:'カスタム',phases:['AC','RE','EX'],main:false,attack:''};modal('行動を登録',`<form id="custom-form" data-id="${esc(a.id)}"><div class="form-grid">${input('name','行動・技の名前',a.name,'text','required')}${select('ppMode','PPの決め方',a.ppMode||'fixed',[['fixed','固定のPP消費'],['creation','創造系：固定追加＋1〜10PP']])}${input('pp','PP消費（創造系では固定追加分のみ）',a.pp,'number','min="0" required')}${input('hp','HP消費',a.hp||0,'number','min="0"')}${input('factor','因子消費（Rd）',a.factor||0,'number','min="0"')}${input('rage','追加の暴走率上昇',a.rage||0,'number','min="0"')}${input('spec','必要スペック',a.spec||0,'number','min="0"')}${select('attack','攻撃種別',a.attack||'',[['','攻撃以外・個別処理'],['melee','格闘'],['weapon','武器'],['power','能力']])}${select('group','分類',a.group,[['応用技','応用技'],['カスタム','特殊武装・SPE等']])}<label class="checkbox"><input name="main" type="checkbox" ${a.main?'checked':''}>メイン行動を使用</label><div class="span-all"><label>宣言可能なフェイズ</label><div class="row wrap" style="margin-top:8px">${Object.entries(Y.phases).map(([k,v])=>`<label class="checkbox"><input type="checkbox" name="phase-${k}" ${a.phases.includes(k)?'checked':''}>${k}</label>`).join('')}</div></div><label class="span-all">効果・条件・メモ<textarea name="note">${esc(a.note)}</textarea></label></div><p class="usage-note">創造系は、ここでは他の効果の固定追加PPだけを設定します（純粋な創造なら0）。創造PPは行動に追加するたび1〜10から選びます。PP消費分の暴走率は自動加算します。特殊武装など、PPを伴わない上昇は「追加の暴走率上昇」に入力します。</p><div class="form-actions">${c().actions.some(x=>x.id===a.id)?`<button type="button" class="danger" data-do="delete-action" data-id="${a.id}">削除</button>`:''}<button type="button" data-do="close">キャンセル</button><button class="primary">行動を保存</button></div></form>`);}
function about(){modal('情報拡張装置【ウールヴハム】の使い方',`<div class="about"><p>① キャラシートを読み込み、内容を確認して保存します。複数キャラは左の一覧で切り替えられます。</p><p>② 探索中／バトル中を切り替えます。バトル中だけフェイズ・ラウンドを進めます。探索中はラウンドや使用済み回数を保持し、バトルへ戻すと直前のフェイズから再開します。技名・効果で候補を絞り、プルダウンから行動・応用技・AE・バーストを選びます。出目が必要な行動は実際の合計を入力し、消費を確認して登録します。</p><p>③ 「盤面の補正」でバフ・デバフを登録すると「期待値・勝率」に反映されます。勝率は1回の対抗判定です。</p><p>④ 履歴の「この時点へ戻る」で、HP・PP・暴走・因子・総消費・ラウンド・補正・相手・BP設定を復元します。巻き戻し前の履歴も残ります。</p><p>ブラウザの保存データを消すとキャラも消えます。「バックアップ」からJSONを書き出すと他端末へ移せます。保存はこのブラウザ・このURLごとです。</p><p class="web-download">Windows版（64bit）は <a href="${WINDOWS_DOWNLOAD}" download="${WINDOWS_FILE}">こちらからダウンロード</a>できます。HTML版とは保存データが別のため、移す場合はバックアップを使ってください。</p><p>HP・PP・暴走率・因子・総消費PPは画面上部に固定表示します。ACで宣言できるバーストは判定バーストと発動バーストだけです。</p><p>「今回の宣言」は幅を広げ、「全幅で表示」から大きく確認できます。Windows版は右端の各しおりでトレイを開閉します。畳んでも宣言途中の内容を保持します。しおり上端をドラッグして移動でき、通常表示への切り替えはありません。</p><p>HP・PP・暴走率・因子・総消費・SPE・カルマはクリックでコピーできます。「全状態をコピー」では一度に1行へまとめます。SPE・カルマは@残り回数、常時、または@∞で表示します。消費アイテムは1個につき1回で、購入価格は使用時に支払いません。効果欄に明記された例外のコストのみ消費します。</p><h3>自動処理と手動処理</h3><p>PP消費と因子獲得、死力、通常の活性補正、宣言時の数値補正を自動計算します。条件付き効果、暴走・臨界の出目、SPE・カルマの固有処理、回復型の活性回復、臨界因子の獲得は「状態を調整」で記録してください。シートの既存履歴は合計値を引き継ぎ、行動明細の履歴はツール内での登録分から始まります。</p><p>読み込み時はExcelの保存済み計算結果を利用します。元のExcelは変更しません。ファイル内容をスクリプトとして実行しません。</p><p>反応型はSSの命中・回避判定にも加算、感覚型は行動値に加算します。増強型は防御を増やさず被ダメージを軽減。「被ダメージ」から実際の判定値を入力すると、装甲と軽減を計算して履歴へ登録します。死力などのHP消費には軽減しません。</p><p>Better Parameterはキャラクター設定でON／OFFを変更できます。ExcelのBP設定、基礎値・特化補正の内訳、攻撃の取得点と計算式を照合し、反映済みの補正は重ねて加算しません。筋力14以上の攻撃ダメージ＋1D6は回復には適用しません。通常はそのまま保存できます。判定できない手入力は入力値を保持し、必要な場合だけ詳細設定で調整できます。耐久18以上の気絶無効は表示します（気絶判定自体は自動実行しません）。</p><p>創造系の技は宣言するたびに創造PPを1〜10から選択します。シートの「3～12PP」は固定追加2PP＋創造1〜10PPとして取り込みます。選択値は暴走率・総消費PP・因子獲得・死力の計算へ反映し、技ごとの内訳を履歴に残します。既存の技は編集画面の「PPの決め方」から創造系へ変更できます。</p><h3>参照</h3><ul><li><a href="https://wolfuls.github.io/YggRW/index.html" target="_blank" rel="noopener">ダイスロール・行為判定</a></li><li><a href="https://wolfuls.github.io/YggRW/rw-rule-ae.html" target="_blank" rel="noopener">アクションエフェクト</a></li><li><a href="https://wolfuls.github.io/YggRW/rw-rule-burst.html" target="_blank" rel="noopener">バースト</a></li><li><a href="https://wolfuls.github.io/YggRW/rw-rule-cm-03.html" target="_blank" rel="noopener">活性タイプ</a></li></ul><p><a href="https://wolfuls.github.io/YggRW/rw-houserules-bp.html" target="_blank" rel="noopener">Better Parameter</a></p><p>非公式セッション補助ツール v1.13 / JSZip: MIT license</p></div><div class="form-actions"><button data-do="export">バックアップ</button><button data-do="restore-file">復元</button><button data-do="manual">手動作成</button><button class="primary" data-do="close">閉じる</button></div>`);}
const handlers={
 close:()=>$('#modal').close(),
 tab:el=>{if(compactDesktop&&window.chrome?.webview&&(popupTitles[el.dataset.tab]||uiDocument!==document)){window.chrome.webview.postMessage('open:'+el.dataset.tab);return;}tab=el.dataset.tab;render();uiDocument.defaultView.scrollTo(0,0);},
 switch:el=>{db.activeId=el.dataset.id;draft=[];desperate=0;note='';save();render();},
 import:importDialog,
 'choose-xlsx':()=>{importMode=$('[name="import-mode"]').value;$('#xlsx-file').click();},
 manual:()=>characterDialog(Y.emptyCharacter(),true),
 demo:()=>{const char=Y.emptyCharacter('サンプル・エージェント');char.source='操作確認用デモ（架空の値）';char.state.rage=58;char.state.spent=14;char.state.factor=4;char.initial=Y.clone(char.state);char.actions.push({id:Y.id(),name:'フォース・インパクト',pp:3,hp:0,factor:0,rage:0,phases:['AC'],group:'応用技',spec:2,note:'デモ用の攻撃発動。能力攻撃力を使用。',attack:'power',main:true});db.characters.push(char);db.activeId=char.id;save();render();},
 'clear-search':()=>{search='';render();$('#action-search').focus();},
 mode:el=>{if(draft.length){toast('登録前の宣言があります。登録するか、候補を外してから切り替えてください。');return;}Y.setMode(c(),el.dataset.mode);save();render();},
 phase:el=>modal('フェイズを切り替えますか？',`<p><b>${esc(el.dataset.phase)} / ${esc(Y.phases[el.dataset.phase])}</b>へ切り替え、今回の宣言${draft.length?'（'+draft.length+'件）':''}とメモを空にします。</p><p class="subtle">まだ登録していない消費は状態に反映されません。</p><div class="form-actions"><button data-do="close">キャンセル</button><button class="primary" data-do="confirm-phase" data-phase="${esc(el.dataset.phase)}">OK・切り替える</button></div>`),
 'confirm-phase':el=>{Y.changePhase(c(),el.dataset.phase);draft=[];desperate=0;note='';save();$('#modal').close();render();},
 'next-round':()=>{if(draft.length){toast('登録前の宣言があります。登録するか、候補を外してください。');return;}Y.nextRound(c());save();render();toast('次のラウンドを開始しました');},
 'add-action':el=>{const a=[...c().actions,...Y.catalog].find(a=>a.id===el.dataset.id);if(!a)return;if(draft.some(r=>Y.sameAction(r.action,a))){toast('この行動は今回の宣言に追加済みです。');return;}const reason=Y.available(c(),a);if(reason){toast(reason);return;}draft.push({action:Y.clone(a),level:1,target:a.target||'hit',result:null,creationPP:null});render();},
 'remove-draft':el=>{draft.splice(Number(el.dataset.index),1);render();},
 roll:el=>{const r=draft[Number(el.dataset.index)];let total=0;const n=r.action.rollDice*r.level;const rolls=[];for(let i=0;i<n;i++){const v=new Uint32Array(1);let x;do{crypto.getRandomValues(v);x=v[0];}while(x>=4294967292);const d=x%6+1;rolls.push(d);total+=d;}r.result=total;render();toast(rolls.join(' + ')+' = '+total);},
 commit:()=>{Y.commit(c(),draft,desperate,note);draft=[];desperate=0;note='';save();render();toast('宣言を登録しました');},
 condition:()=>conditionDialog(),
 'condition-roll':el=>{const f=$('#condition-form');f.elements[el.dataset.field].value=randomDice(2);updateConditionPreview();},
 'copy-resource':el=>copyResource(el.dataset.key),
 'inventory-add':()=>inventoryDialog(),
 'inventory-edit':el=>inventoryDialog(c().actions.find(a=>a.id===el.dataset.id)),
 'inventory-import':()=>{importMode='inventory';$('#xlsx-file').click();},
 damage:()=>damageDialog(),
 adjust:()=>adjustDialog(),
 'resolve-pending':()=>adjustDialog(true),
 'add-buff':()=>buffDialog(),
 'edit-buff':el=>buffDialog(c().state.buffs.find(b=>b.id===el.dataset.id)),
 'delete-buff':el=>{const s=Y.clone(c().state),b=s.buffs.find(b=>b.id===el.dataset.id);s.buffs=s.buffs.filter(b=>b.id!==el.dataset.id);Y.record(c(),'補正を削除：'+b.name,s,{},'buff');save();$('#modal').close();render();},
 'custom-action':()=>customDialog(),
 'edit-action':el=>customDialog(c().actions.find(a=>a.id===el.dataset.id)),
 'delete-action':el=>{c().actions=c().actions.filter(a=>a.id!==el.dataset.id);save();$('#modal').close();render();},
 'edit-character':()=>characterDialog(c()),
 rollback:el=>{const id=el.dataset.id,e=c().history.find(e=>e.id===id),s=id==='initial'?c().initial:e?.after;if(!s)return;modal('この状態へ巻き戻す',`<p>${esc(e?.title||'読み込み時の状態')}</p><div class="notice">${Y.isBattle(s)?'R'+s.round+' / '+Y.phases[s.phase]:'探索中'} / HP ${s.hp} / PP ${s.pp} / 暴走 ${s.rage}% / 因子 ${s.factor} Rd / 総消費 ${s.spent}PP</div><p class="subtle">盤面の補正、相手の状態、BP設定も復元します。既存の履歴は残ります。</p><div class="form-actions"><button data-do="close">キャンセル</button><button class="primary" data-do="confirm-rollback" data-id="${esc(id)}">この状態へ戻る</button></div>`);},
 'confirm-rollback':el=>{Y.rollback(c(),el.dataset.id);draft=[];desperate=0;save();$('#modal').close();render();toast('選んだ状態に戻しました');},
 'delete-character':()=>modal('キャラクターを削除',`<p>「${esc(c().name)}」とこのキャラの全履歴を削除します。</p><div class="form-actions"><button data-do="export">先にバックアップ</button><button data-do="close">キャンセル</button><button class="danger" data-do="confirm-delete">削除する</button></div>`),
 'confirm-delete':()=>{db.characters=db.characters.filter(x=>x.id!==c().id);db.activeId=db.characters[0]?.id;draft=[];desperate=0;save();$('#modal').close();render();},
 export:()=>download(JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),'Ulfhamr-Backup-'+new Date().toISOString().slice(0,10)+'.json'),
 'export-raw':()=>download(localStorage.getItem(KEY)||'','Ulfhamr-Recovery.json'),
 'restore-file':()=>document.querySelector('#json-file').click(),
 'export-history':()=>{const rows=[['日時','進行モード','ラウンド','フェイズ','行動','HP','PP','暴走率','因子（Rd）','総消費PP','今回消費PP','今回総消費','メモ'],...c().history.map(e=>[e.time,e.phase==='EX'?'探索中':'バトル中',e.phase==='EX'?'':e.round,e.phase,e.title,e.after.hp,e.after.pp,e.after.rage,e.after.factor,e.after.spent,e.detail?.pp||0,e.detail?.spent||0,e.detail?.note||''])];download('\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'Ulfhamr-History.csv','text/csv;charset=utf-8');},
 'opponent-from-character':()=>modal('保存キャラを比較対象にする',`<p class="subtle">選んだキャラの現在の活性・補正を含めた値をコピーします。</p><div class="form-actions">${db.characters.map(x=>`<button data-do="set-opponent" data-id="${esc(x.id)}">${esc(x.name)}</button>`).join('')}</div>`),
 'set-opponent':el=>{const other=db.characters.find(x=>x.id===el.dataset.id),v=Y.effective(other,compareOpts.mental?'ss':'dodge');const s=Y.clone(c().state);s.opponent={name:other.name,hp:other.state.hp,fixed:v.fixed,dice:v.dice,defense:Y.effective(other,'defense').fixed,resist:Y.effective(other,'resist').fixed,rage:other.state.rage,activation:other.activation};Y.record(c(),'比較対象：'+other.name,s,{},'opponent');save();$('#modal').close();render();},
 about
};

function withSurface(doc,fn){
 const previousDoc=uiDocument,previousTab=tab,context=surfaces.get(doc);
 uiDocument=doc;tab=context.tab;
 try{return fn();}finally{context.tab=tab;uiDocument=previousDoc;tab=previousDoc===doc?context.tab:previousTab;}
}
const surfaceListeners=[];
function listen(doc,type,handler,options){
 if(doc===document)surfaceListeners.push([type,handler,options]);
 doc.addEventListener(type,e=>withSurface(doc,()=>handler(e)),options);
}
function syncSurfaceLocks(){
 let owner=null;for(const doc of surfaces.keys())if(doc.querySelector('#modal')?.open){owner=doc;break;}
 for(const doc of surfaces.keys()){const app=doc.querySelector('#app');if(app)app.inert=!!owner&&owner!==doc;}
}
function render(exceptDocument=null){
 surfaces.get(uiDocument).tab=tab;
 for(const [doc,context] of surfaces){
  if(doc===exceptDocument)continue;
  if(doc!==document&&doc.defaultView.closed){surfaces.delete(doc);continue;}
  withSurface(doc,()=>{
   if(doc===document){renderOne();return;}
   doc.body.className='companion-mode independent-window';
   $('#app').innerHTML='<main class="main">'+(c()?'<p class="window-character">'+esc(c().name)+'</p>'+(tab==='actions'?actionsView():tab==='compare'?compareView():buffView()):'<div class="panel"><h2>'+popupTitles[tab]+'</h2><p>「今回の宣言」からキャラクターを読み込んでください。</p><button data-do="tab" data-tab="draft">今回の宣言を開く</button></div>')+'</main>';
   if(c()&&tab==='compare')calculate();
  });
 }
 syncSurfaceLocks();
}
window.addEventListener('ygg-open-popup',e=>{
 const key=e.detail;if(!popupTitles[key]||!window.chrome?.webview)return;
 const child=window.open('about:blank','ygg-'+key,'popup,width=760,height=960');
 if(!child){window.chrome.webview.postMessage('popup-failed:'+key);toast('ウィンドウを開けませんでした。もう一度しおりを押してください。');return;}
 // Wait until the native WebView is attached; do not run another application instance.
 const attach=()=>{
  try{
   if(child.closed)return;
   const doc=child.document;
   if(surfaces.has(doc))return;
   doc.open();doc.write('<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+popupTitles[key]+' — 情報拡張装置【ウールヴハム】</title><link rel="stylesheet" href="https://ygg-round.example/styles.css"></head><body><input id="xlsx-file" type="file" accept=".xlsx" hidden><div id="app"></div><div id="toast" role="status"></div><dialog id="modal"><div id="modal-content"></div></dialog></body></html>');doc.close();
   surfaces.set(doc,{tab:key});bindImport(doc);
   for(const [type,handler,options] of surfaceListeners)listen(doc,type,handler,options);
   doc.addEventListener('close',syncSurfaceLocks,true);
   render();
  }catch(error){toast('独立ウィンドウの初期化に失敗しました：'+error.message);}
 };
 attach();
});
window.addEventListener('ygg-hide-popup',e=>{
 for(const [doc,context] of surfaces)if(doc!==document&&context.tab===e.detail)doc.querySelector('#modal')?.close();
 syncSurfaceLocks();
});
document.addEventListener('close',syncSurfaceLocks,true);

window.addEventListener('ygg-desktop',e=>{const d=e.detail;if(!d||typeof d.compact!=='boolean'||!['actions','draft','compare','buffs','history','character'].includes(d.tab))return;const previousTab=tab;compactDesktop=d.compact;if(!$('#modal').open)tab=d.tab;else toast('編集中の画面を閉じてからトレイを切り替えてください。');surfaces.get(document).tab=tab;render();if(tab!==previousTab)window.scrollTo(0,0);});
listen(document,'click',e=>{const el=e.target.closest('[data-do]');if(!el)return;try{handlers[el.dataset.do]?.(el);}catch(err){toast(err.message||String(err));}});
listen(document,'toggle',e=>{const el=e.target;if(el.matches?.('details[data-action-group]')&&el.isConnected&&!search){if(el.open)foldedGroups.delete(el.dataset.actionGroup);else foldedGroups.add(el.dataset.actionGroup);}},true);
listen(document,'input',e=>{const el=e.target;if(el.form?.id==='condition-form')updateConditionPreview();if(el.form?.id==='damage-form')updateDamagePreview();if(el.form?.id==='character-form')updateBPPreview();if(el.id==='action-note')note=el.value;if(el.id==='action-search'){search=el.value;const pos=el.selectionStart;render();$('#action-search').focus();$('#action-search').setSelectionRange(pos,pos);}});
listen(document,'change',e=>{const el=e.target;try{
 if(el.form?.id==='condition-form')updateConditionPreview();if(el.form?.id==='damage-form')updateDamagePreview();if(el.form?.id==='character-form')updateBPPreview();
 if(el.name==='owned-preset'){const preset=Y.ownedCatalog.find(a=>a.catalogKey===el.value);if(preset)inventoryDialog({...Y.clone(preset),id:editingOwned.id,quantity:1});return;}
 if(el.id==='companion-character'){handlers.switch({dataset:{id:el.value}});return;}
 if(el.id==='action-pick'){
  selectedActionId=el.value;const picked=[...c().actions,...Y.catalog].find(a=>a.id===selectedActionId),picker=el.closest('.action-picker');
  const reason=picked?(draft.some(r=>Y.sameAction(r.action,picked))?'追加済み':Y.available(c(),picked)):'';
  const add=picker.querySelector('[data-do="add-action"]');add.dataset.id=selectedActionId;add.disabled=!picked||!!reason;add.textContent=reason==='追加済み'?'追加済み':'＋ 追加';
  const hint=picker.querySelector('.picker-hint');hint.textContent=el.querySelectorAll('option[value]:not([value=""])').length+'件'+(reason?'　'+reason:'');
  picker.querySelector('.selection-detail')?.remove();if(picked)picker.insertAdjacentHTML('beforeend',actionDetails(picked));return;
 }
 if(el.dataset.draft){const r=draft[Number(el.dataset.index)];r[el.dataset.draft]=['target','itemTarget'].includes(el.dataset.draft)?el.value:el.value===''?null:Number(el.value);render();}
 if(el.id==='desperate'){desperate=Number(el.value);render();}
 if(el.dataset.buffToggle){const s=Y.clone(c().state),b=s.buffs.find(b=>b.id===el.dataset.buffToggle);b.active=el.checked;Y.record(c(),'補正'+(b.active?'ON':'OFF')+'：'+b.name,s,{},'buff');save();render();}
 if(el.name.startsWith('compare-')){const key=el.name.slice(8);compareOpts[key]=key==='mental'?el.value==='ss':el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(key==='mental')render();else calculate();}
 if(el.name.startsWith('enemy-')){const s=Y.clone(c().state),key=el.name.slice(6);const textKey=['name','activation'].includes(key);s.opponent[key]=textKey?el.value:Number(el.value);if(!Number.isFinite(s.opponent[key])&&!textKey)throw Error('相手の数値を確認してください');Y.record(c(),'比較対象を更新：'+s.opponent.name,s,{},'opponent');save();render(uiDocument);calculate();}
 }catch(err){toast(err.message);}});
listen(document,'submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f),n=k=>{const v=Number(d.get(k));if(!Number.isFinite(v)||!Number.isInteger(v))throw Error('整数で入力してください：'+k);return v;};try{
 if(f.id==='character-form'){
  const isNew=!!pendingImport,original=isNew?pendingImport:c(),char=Y.clone(original),previousPPBonus=Y.bpBonuses(original).ppMax,resolved=[];
  if(isNew){char.actions.forEach((a,i)=>(a.importMissing||[]).forEach(m=>{const key='import-action-'+i+'-'+m.field;if(!d.has(key)||String(d.get(key)).trim()==='')throw Error(a.name+'の'+(m.field==='pp'?(a.ppMode==='creation'?'固定追加PP（創造1〜10PPを除く）':'消費PP'):'必要スペック')+'を入力してください');const value=n(key);if(value<0)throw Error('消費PP・必要スペックは0以上です');resolved.push({a,field:m.field,value});}));}
  char.name=String(d.get('name')).trim();if(!char.name)throw Error('キャラクター名を入力してください');char.activation=d.get('activation');
  for(const k of Object.keys(char.stats)){if(['params','skills'].includes(k))continue;if(d.has(k))char.stats[k]=n(k);}
  char.stats.params=char.stats.params.map((_,i)=>n('param'+i));for(const k of Y.skillNames)char.stats.skills[k]=n('skill-'+k);
  const bp=readBPForm(f);
  if(isNew){for(const k of['hp','pp','rage','factor','spent','hpMax','ppMax'])char.state[k]=n('state-'+k);if(char.state.spent<0||char.state.pp<0||char.state.rage<0||char.state.hpMax<1||char.state.ppMax<0)throw Error('状態値の範囲を確認してください');for(const item of resolved)item.a[item.field]=item.value;for(const a of char.actions)delete a.importMissing;Y.setBP(char,bp,{initial:true,previousPPBonus});db.characters.push(char);db.activeId=char.id;pendingImport=null;draft=[];}
  else {if(JSON.stringify(bp)!==JSON.stringify(Y.bpConfig(original.state))||previousPPBonus!==Y.bpBonuses(char,{...char.state,bp}).ppMax)Y.setBP(char,bp,{previousPPBonus});db.characters[db.characters.findIndex(x=>x.id===char.id)]=char;}
 }
 else if(f.id==='condition-form'){Y.applyCondition(c(),conditionValues(f));}
 else if(f.id==='inventory-form'){
  const a={...editingOwned,name:String(d.get('name')).trim(),group:d.get('group'),quantity:n('quantity'),pp:n('pp'),hp:n('hp'),factor:n('factor'),rage:n('rage'),useLimit:n('useLimit'),usePeriod:d.get('usePeriod'),pressure:d.get('pressure')===''?null:n('pressure'),passive:d.has('passive'),main:d.has('main'),note:String(d.get('note')),needsReview:false,phases:Object.keys(Y.phases).filter(k=>d.has('phase-'+k))};
  if(!a.name||!a.phases.length||[a.quantity,a.pp,a.hp,a.factor,a.rage,a.useLimit].some(x=>x<0))throw Error('名前・コスト・宣言フェイズを確認してください');
  if(c().actions.some(x=>x.id!==a.id&&x.owned&&x.group===a.group&&x.name.normalize('NFKC')===a.name.normalize('NFKC')))throw Error('登録済みです。既存の所持品を編集してください');
  a.owned=true;a.rulesEdited=true;a.consumable=a.group==='消費アイテム';if(a.consumable){a.level=true;a.max=99;}else delete a.level;
  const s=Y.clone(c().state);s.ownedStock=s.ownedStock||{};s.ownedUses=s.ownedUses||{};const remaining=n('remaining');if(remaining<0||a.useLimit&&!a.consumable&&remaining>a.useLimit)throw Error('残数・残り使用回数を確認してください');
  if(a.consumable)s.ownedStock[a.id]=remaining;else if(a.useLimit)s.ownedUses[Y.ownedUseKey(a,s)]=a.useLimit-remaining;
  c().actions=c().actions.filter(x=>x.id!==a.id);c().actions.push(a);Y.record(c(),'所持品を登録：'+a.name,s,{},'inventory');draft=draft.filter(r=>r.action.id!==a.id);
 }

 else if(f.id==='damage-form'){Y.takeDamage(c(),n('damageRaw'),d.get('damageKind'),String(d.get('damageNote')));}
 else if(f.id==='adjust-form'){const char=c(),s=Y.clone(char.state),cost=n('costPP');if(cost<0||cost>s.pp)throw Error('消費PPは0〜残PPの範囲で指定してください');const gain=Math.floor((s.spent+cost)/5)-Math.floor(s.spent/5);s.hpMax=n('hpMax');s.ppMax=n('ppMax');s.hp=Math.min(s.hpMax,s.hp+n('hp'));s.pp=Math.min(s.ppMax,s.pp-cost+n('pp'));if(s.pp<0)throw Error('PPが0未満になります');s.rage=Math.max(0,s.rage+cost+n('rage'));s.factor+=n('factor')+gain;s.spent+=cost;if(f.dataset.resolve==='true')s.pending=[];else for(const t of[50,60,70,80,90,100,110,120,130,140,150])if(char.state.rage<t&&s.rage>=t)s.pending.push(t+'%到達：活性・暴走・臨界処理');Y.record(char,String(d.get('reason')),s,{pp:cost,spent:cost,gained:gain,note:String(d.get('reason'))},'adjust');}
 else if(f.id==='buff-form'){const s=Y.clone(c().state),b={id:f.dataset.id,name:String(d.get('name')),target:d.get('target'),stat:d.get('stat'),flat:n('flat'),dice:n('dice'),mult:Number(d.get('mult')),endRound:d.get('endRound')?n('endRound'):null,active:d.has('active')};if(!b.name.trim())throw Error('補正名を入力してください');s.buffs=s.buffs.filter(x=>x.id!==b.id);s.buffs.push(b);Y.record(c(),'補正を登録：'+b.name,s,{},'buff');}
 else if(f.id==='custom-form'){const a={...c().actions.find(x=>x.id===f.dataset.id),id:f.dataset.id,name:String(d.get('name')),pp:n('pp'),ppMode:d.get('ppMode')||'fixed',hp:n('hp'),factor:n('factor'),rage:n('rage'),spec:n('spec'),group:d.get('group'),attack:d.get('attack')||null,main:d.has('main'),note:String(d.get('note')),phases:Object.keys(Y.phases).filter(k=>d.has('phase-'+k))};if(!a.name.trim()||!a.phases.length)throw Error('名前と宣言可能なフェイズを指定してください');if(!['fixed','creation'].includes(a.ppMode))throw Error('PPの決め方を確認してください');if([a.pp,a.hp,a.factor,a.rage,a.spec].some(x=>x<0))throw Error('コストは0以上にしてください');c().actions=c().actions.filter(x=>x.id!==a.id);c().actions.push(a);}
 else return;
 save();$('#modal').close();render();toast('保存しました');
 }catch(err){toast(err.message);}});
function bindImport(doc){doc.querySelector('#xlsx-file').addEventListener('change',async e=>{
 const file=e.target.files[0];if(!file)return;const mode=importMode,targetId=c()?.id;
 withSurface(doc,()=>toast('キャラシートを読み込んでいます…'));
 try{const char=await readCharacterXlsx(file,mode);withSurface(doc,()=>{
  if(mode==='inventory'){const target=db.characters.find(x=>x.id===targetId);if(!target)throw Error('読込先のキャラクターが見つかりません');const added=Y.mergeOwned(target,char);save();render();toast(added+'件の所持品を追加しました（登録済みの残数は保持）');}
  else characterDialog(char,true);
 });}catch(err){withSurface(doc,()=>modal('読み込めませんでした',`<div class="error">${esc(err.message)}</div><div class="form-actions"><button data-do="close">閉じる</button></div>`));}finally{e.target.value='';}
});}
bindImport(document);
$('#json-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('30MB以下のバックアップを選んでください');const imported=Y.validateDatabase(JSON.parse(await file.text()));for(const char of imported.characters){char.id=Y.id();char.name+='（復元）';db.characters.push(char);}db.activeId=db.characters.at(-1)?.id;if(storageError)throw Error('元データ保護のため保存を停止しています。元データを書き出し、別ブラウザでこのバックアップを復元してください。');save();$('#modal').close();render();toast(imported.characters.length+'件を追加しました。既存データは保持しています。');}catch(err){toast('復元できませんでした：'+err.message);}finally{e.target.value='';}});
window.addEventListener('storage',e=>{if(e.key===KEY){storageError='別のタブでデータが更新されたため保存を停止しました。再読み込みして最新状態を確認してください。';toast(storageError);}});
render();
})();
